//! A `tantra_library` projected scene (Predictive Ranges bands + PR zone-touch markers,
//! generated by the Python kernel) projects onto the TUI StrategyLab canvas through the
//! same `project_overlay_scene` path as strategy-loop scenes: no per-indicator TUI code.

use rust_decimal::Decimal;
use tantra_ui_charts::scene::OverlayScene;
use tantra_ui_core::{LoopCandle, build_layer_pills, project_overlay_scene};

const LIBRARY_PROJECTION: &str =
    include_str!("../../tantra-ui-charts/tests/fixtures/python_library_projection_scene.json");

fn candles(n: usize) -> Vec<LoopCandle> {
    // Same synthetic series the fixture was generated from (tail window of 60 bars,
    // close = 1002 + 3*i for the full 300-bar series).
    (0..n)
        .map(|i| {
            let base = Decimal::from(1000 + 3 * (240 + i as i64));
            LoopCandle {
                index: i,
                timestamp: format!("bar-{i}"),
                open: base,
                high: base + Decimal::from(4),
                low: base - Decimal::from(2),
                close: base + Decimal::from(2),
                volume: Decimal::from(1000),
            }
        })
        .collect()
}

#[test]
fn library_scene_projects_onto_strategy_lab_canvas() {
    let scene: OverlayScene =
        serde_json::from_str(LIBRARY_PROJECTION).expect("library scene deserializes");
    let projected = project_overlay_scene(&candles(60), &scene);
    assert!(
        !projected.bands.is_empty(),
        "PR bands project as rect bands"
    );
    assert!(
        !projected.signals.is_empty(),
        "detector events project as glyphs"
    );
    assert!(
        !projected.overlay_traces.is_empty() || !projected.subpane_traces.is_empty(),
        "indicator series project as traces"
    );
    assert!(projected.y_min < projected.y_max);
    assert_eq!(build_layer_pills(&scene).len(), 6);
}
